using System;using System.Collections;using System.Drawing;using System.Windows.Forms;using QuanLyBanDienThoai.BUS;using QuanLyBanDienThoai.DTO;
namespace QuanLyBanDienThoai.GUI {public class FormNhapHang:Form {
 readonly PhieuNhapHangBUS bus=new PhieuNhapHangBUS();readonly ArrayList ds=new ArrayList();readonly ComboBox ncc=new ComboBox(),nv=new ComboBox(),dt=new ComboBox();readonly NumericUpDown sl=new NumericUpDown(),gia=new NumericUpDown();readonly DataGridView grid=new DataGridView();readonly Label total=new Label();
 public FormNhapHang(){Text="Lập phiếu nhập hàng";Width=1050;Height=680;var top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=120,AutoScroll=true};Add(top,"Nhà cung cấp",ncc);Add(top,"Nhân viên",nv);Add(top,"Điện thoại",dt);Add(top,"Số lượng",sl);Add(top,"Giá nhập",gia);sl.Minimum=1;sl.Maximum=100000;gia.Minimum=1;gia.Maximum=100000000000;gia.ThousandsSeparator=true;var add=new Button{Text="Thêm dòng",Width=105};top.Controls.Add(add);add.Click+=(s,e)=>Them();var del=new Button{Text="Xóa dòng",Width=105};top.Controls.Add(del);del.Click+=(s,e)=>{if(grid.CurrentRow?.DataBoundItem is ChiTietPhieuNhapHang d){ds.Remove(d);RefreshGrid();}};var save=new Button{Text="Lập phiếu nhập",Width=125};top.Controls.Add(save);save.Click+=(s,e)=>Luu();total.Dock=DockStyle.Bottom;total.Height=35;total.Font=new Font(Font,FontStyle.Bold);grid.Dock=DockStyle.Fill;grid.ReadOnly=true;grid.SelectionMode=DataGridViewSelectionMode.FullRowSelect;grid.AllowUserToAddRows=false;Controls.Add(grid);Controls.Add(total);Controls.Add(top);
 try{Bind(ncc,new NhaCungCapBUS().GetAll(),"TenNCC","MaNCC");Bind(nv,new NhanVienBUS().GetAll(),"HoTen","MaNV");Bind(dt,new DienThoaiBUS().GetAll(),"TenHienThi","MaDT");}catch(Exception e){MessageBox.Show(e.Message);}RefreshGrid();}
 void Add(FlowLayoutPanel panel,string title,Control c){var p=new Panel{Width=220,Height=55};p.Controls.Add(new Label{Text=title,Dock=DockStyle.Top});c.Dock=DockStyle.Bottom;p.Controls.Add(c);panel.Controls.Add(p);}
 void Bind(ComboBox c,ArrayList ds,string display,string value){c.DropDownStyle=ComboBoxStyle.DropDownList;c.DataSource=ds;c.DisplayMember=display;c.ValueMember=value;}
 int Selected(ComboBox c)=>c.SelectedValue is int v?v:0;
 void Them(){string err=bus.TaoDong(ds,Selected(dt),(int)sl.Value,gia.Value);if(err!="")MessageBox.Show(err);else RefreshGrid();}
 void RefreshGrid(){grid.DataSource=null;grid.DataSource=ds.ToArray();total.Text="Tổng tiền: "+bus.TinhTongTienNhap(ds).ToString("N0")+" đ";}
 void Luu(){string err=bus.LuuPhieuNhap(new PhieuNhapHang{MaNCC=Selected(ncc),MaNV=Selected(nv)},ds,out int id);if(err!=""){MessageBox.Show(err);return;}MessageBox.Show("Đã lưu phiếu nhập #"+id);ds.Clear();RefreshGrid();}
} }